package com.smartbus.booking.config; import org.springframework.boot.CommandLineRunner; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Component; @Component public class DatabaseFixer implements CommandLineRunner { private final JdbcTemplate jdbcTemplate; public DatabaseFixer(JdbcTemplate jdbcTemplate) { this.jdbcTemplate = jdbcTemplate; } @Override public void run(String... args) { try { jdbcTemplate.execute("ALTER TABLE routes ADD route_data TEXT"); System.out.println("Fixed routes table"); } catch (Exception e) { System.out.println("Routes table already fixed"); } try { jdbcTemplate.execute("ALTER TABLE trips ADD route_data TEXT"); System.out.println("Fixed trips table"); } catch (Exception e) { System.out.println("Trips table already fixed"); } } }